// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(uint256 blockLag, bytes32 guessHash) public {
        vm.assume(blockLag >= 2);
        blockLag = bound(blockLag, 2, 1000000);

        address user = address(0xBEEF);
        vm.deal(user, 1 ether);

        vm.roll(5);
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(guessHash);

        vm.roll(block.number + blockLag);

        uint256 balanceBefore = address(c).balance;

        vm.prank(user);
        c.settle();

        uint256 balanceAfter = address(c).balance;

        bytes32 correctAnswer = keccak256(abi.encodePacked(blockhash(block.number - blockLag + 1)));

        if (guessHash != correctAnswer) {
            assertTrue(balanceAfter != balanceBefore - 2 ether);
        } else {
            assertTrue(balanceAfter == balanceBefore - 2 ether);
        }
    }
}
